];

const RECEIPT_NOT_NULL = new Set(['attempt_id','owner_id','scope_kind','request_id','permit_id',
  'provider','model_name','called_at','dispatch','outcome','cost_status','created_at','updated_at']);
const RECEIPT_CONSTRAINTS = [
