修改已有文档前先 read；更新必须保留 scenario_id 并显式 replaces 旧 version_id；合并所有旧主题。
可以使用简单 xxx.md 文件名，禁止斜杠、绝对路径、目录和读取工作区外内容。
write/edit 仅暂存，永不发布；结束工具调用后会交给独立核验。
不得为减少文件数量合并无关主体或独立事件；无法保全来源与原意时明确失败。
场景正文使用下列格式，不使用 created/updated/summary/heat 头；当前文件总数不得超过 ${maxScenes}。
<!-- META {"topic_key":"work","title":"工作经历","hint":"有来源的经历"} -->
段落正文
<!-- SOURCES [{"memory_id":"本次真实ID","revision":1}] -->
`;
}
function getSceneSystemPrompt(maxScenes: number, _mode: MemoryPromptMode = "chat"): string { return buildSceneSystemPrompt(maxScenes); }

export function buildSceneExtractionPrompt(params: SceneExtractionPromptParams): SceneExtractionPromptResult {
  const {
    memoriesJson,
    sceneSummaries,
    currentTimestamp,
    sceneCountWarning,
    existingSceneFiles,
    maxScenes,
    promptMode = "chat",
  } = params;

  const warningSection = sceneCountWarning
    ? `\n⚠️ **场景数量警告**: ${sceneCountWarning}\n`
    : "";

  const fileListSection = existingSceneFiles && existingSceneFiles.length > 0
    ? `### 📁 已有场景文件清单（仅以下文件可 read）\n${existingSceneFiles.map((f) => `- \`${f}\``).join("\n")}\n`
    : `### 📁 已有场景文件清单\n（当前无已有场景文件）\n`;

  const userPrompt = `**输出语言**：场景文件内容使用下方 New Memories List 中记忆的主导语言。
${warningSection}
### 1️⃣ New Memories List
${memoriesJson}

### 2️⃣ Existing Scene Blocks Summary
${sceneSummaries}

### 3️⃣ Current Timestamp
${currentTimestamp}

${fileListSection}`;

  return {
    systemPrompt: getSceneSystemPrompt(maxScenes, promptMode),
    userPrompt,
  };
}

backend-ts/src/wechat-history-enrollment.content:
/** 首连历史同意覆盖当次完整元数据快照；后续运行时新绑定由范围入口按 ADR-100 授权。 */
import { createHash } from 'node:crypto';
import type pg from 'pg';
import { HostStorageError } from './host-storage.ts';
import { grantBindingHistory } from './sync-scope-history.ts';
export interface HistorySession { username:string; display_name:string; chat_type:string }
export async function enrollHistorySnapshot(client:pg.Client, ownerId:string, accountScope:string,
  sessions:readonly HistorySession[] | undefined, at:Date, check:()=>void):Promise<void> {
  if (!Array.isArray(sessions) || sessions.length > 5000) throw new HostStorageError('setup_request_invalid');
  const seen = new Set<string>();
  for (const row of sessions) {
    if (!row || typeof row.username !== 'string' || !row.username.trim() || row.username.length > 255
      || typeof row.display_name !== 'string' || row.display_name.length > 4096 || typeof row.chat_type !== 'string'
      || seen.has(row.username)) throw new HostStorageError('setup_request_invalid');
    seen.add(row.username);
  }
  const existing = (await client.query("SELECT id,contact_id,conversation_locator,status FROM public.conversation_binding WHERE owner_id=$1 AND channel='wechat' AND account_scope=$2",[ownerId,accountScope])).rows;
  const excluded = new Set((await client.query("SELECT encode(locator_hash,'hex') AS hash FROM public.wechat_sync_exclusion WHERE owner_id=$1 AND channel='wechat' AND account_scope=$2",[ownerId,accountScope])).rows.map(row=>row.hash));
  const identities = (await client.query("SELECT external_id,contact_id,status FROM public.channel_identity WHERE owner_id=$1 AND channel='wechat' AND external_id=ANY($2)",[ownerId,[...seen]])).rows;
  const ids:string[]=[];
  const started=performance.now();
  for (const session of sessions) {
    check();
    if (performance.now()-started > 10_000) throw new HostStorageError('wechat_history_snapshot_budget');
    if (session.chat_type !== 'private' || excluded.has(createHash('sha256').update(session.username).digest('hex'))) continue;
    const bindings=existing.filter(row=>row.conversation_locator===session.username);
    const matches=identities.filter(row=>row.external_id===session.username);
    const active=new Set<string>(matches.filter(row=>row.status==='active').map(row=>row.contact_id));
    if (active.size>1 || bindings.filter(row=>row.status==='active').length>1) throw new HostStorageError('wechat_identity_conflict');
    if (bindings.some(row=>row.status!=='active') || matches.length && !active.size) continue;
    const bound=bindings[0];
    if (bound) {
      if (active.size && !active.has(bound.contact_id)) throw new HostStorageError('wechat_identity_conflict');
      ids.push(bound.id); continue;
    }
    const name=session.display_name || session.username;
    const contact=active.size ? [...active][0] : (await client.query('INSERT INTO public.contact(owner_id,display_name) VALUES($1,$2) RETURNING id',[ownerId,name])).rows[0].id;
    const id=(await client.query("INSERT INTO public.conversation_binding(owner_id,contact_id,channel,account_scope,conversation_locator,display_name) VALUES($1,$2,'wechat',$3,$4,$5) RETURNING id",[ownerId,contact,accountScope,session.username,name])).rows[0].id;
    await client.query('INSERT INTO public.wechat_observation_baseline(owner_id,contact_id,binding_id,conversation_locator,baseline_at) VALUES($1,$2,$3,$4,$5)',[ownerId,contact,id,session.username,at]);
    ids.push(id);
  }
  await grantBindingHistory(client,{ownerId,accountScope},ids,at);
  check();
}

backend-ts/src/wechat-scope-json.ts.content:
/** 保留旧授权JSON合同：重复键、坏UTF-8或空正文都不能被解释为确认。 */
export function parseWechatScopeJson(input: string | Buffer): unknown {
  const text = Buffer.isBuffer(input) ? new TextDecoder('utf-8',{fatal:true}).decode(input) : input;
  const value: unknown = JSON.parse(text);
  const scopes: (Set<string> | null)[] = [];
  // JSON.parse已验证语法；词法扫描只补它不会拒绝的同对象重复键。
  const tokens = /"(?:\\.|[^"\\])*"|[{}\[\]]/g;
  for (let token; (token = tokens.exec(text)) !== null;) {
    if (token[0] === '{') scopes.push(new Set());
    else if (token[0] === '[') scopes.push(null);
    else if (token[0] === '}' || token[0] === ']') scopes.pop();
    else {
      let next = tokens.lastIndex;
      while (/\s/.test(text[next] ?? '') && next < text.length) next++;
      if (text[next] !== ':') continue;
      const keys = scopes.at(-1);
      const key = JSON.parse(token[0]) as string;
      if (!keys || keys.has(key)) throw new Error('invalid_json');
      keys.add(key);
    }
  }
  return value;
}

backend-ts/src/wechat-sessions.ts.content:
/** 只读会话元数据边界；DSH 0.2.1-rc.2 的 session 服务不承担渠道身份。
 * 官方 687f282 packages/core/session/src/index.ts 定义模型会话；本模块不调用模型或注册 Tool。
 */
import { BoundedWechatCliRunner, parseConfiguredWechatAccount } from './wechat-setup-probe.ts';

export interface WechatSessionCandidate {
  username: string;
  display_name: string;
  chat_type: 'private';
  last_timestamp: number | null;
}
export class WechatSessionsError extends Error {
  readonly code: string;
  constructor(code: string) { super('微信会话元数据核验失败。'); this.code = code; }
}
const fail = (code = 'cli_output_invalid'): never => { throw new WechatSessionsError(code); };
function object(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return fail();
  return value as Record<string, unknown>;
}

/** 仅在明确的列表请求或有效全部私聊授权内调用；本模块不建立授权。 */
export class WechatSessions {
  private readonly runner: BoundedWechatCliRunner;
  private closed = false;
  constructor(options: { executable: string; environment?: NodeJS.ProcessEnv }) {
    this.runner = new BoundedWechatCliRunner(options);
  }
  async sessions(options: { type_filter: 'private'; limit?: number; expected_account?: string; signal?: AbortSignal }): Promise<WechatSessionCandidate[]> {
    const limit = options.limit ?? 5000;
    if (options.type_filter !== 'private' || !Number.isInteger(limit) || limit < 1 || limit > 5000
      || options.expected_account !== undefined && !/^[A-Za-z0-9_.@-]{1,255}$/.test(options.expected_account)) return fail('cli_invalid_argument');
    const check = () => {
      if (this.closed) return fail('runtime_stopping');
      if (options.signal?.aborted) return fail('cli_cancelled');
    };
    check();
    const status = ['status', '--include-debug', '--strict-read-only'];
    const before = parseConfiguredWechatAccount(await this.runner.run(status, 5000, options.signal));
    check();
    if (options.expected_account !== undefined && before !== options.expected_account) return fail('cli_account_changed');
    const data = object(await this.runner.run(['sessions', '--type-filter', 'private', '--limit', String(limit), '--strict-read-only'], 1000, options.signal));
    check();
    // 没有分页结束证据时，达到上限意味着可能截断，不能作为完整授权快照。
    if (!Array.isArray(data.sessions) || data.sessions.length >= limit) return fail();
    const candidates: WechatSessionCandidate[] = [];
    const identities = new Set<string>();
    for (const raw of data.sessions) {
      const row = object(raw);
      if (typeof row.chat_type !== 'string' || !row.chat_type.trim()) return fail();
      if (row.chat_type !== 'private') continue;
      if (typeof row.username !== 'string' || !/^[A-Za-z0-9_.@-]{1,255}$/.test(row.username)) return fail();
      // 不从展示名补造身份，也不接受伪装为私聊的群聊和公众号定位标识。
      if (row.username.endsWith('@chatroom') || row.username.startsWith('gh_')) continue;
      if (identities.has(row.username)) return fail('cli_identity_conflict');
      identities.add(row.username);
      if (typeof row.display_name !== 'string' || row.display_name.length > 4096) return fail();
      const timestamp = row.last_timestamp ?? null;
      if (timestamp !== null && (typeof timestamp !== 'number' || !Number.isSafeInteger(timestamp))) return fail();
      candidates.push({ username: row.username, display_name: row.display_name.trim() ? row.display_name : row.username,
        chat_type: 'private', last_timestamp: timestamp });
    }
    const after = parseConfiguredWechatAccount(await this.runner.run(status, 5000, options.signal));
    check();
    if (after !== before) return fail('cli_account_changed');
    return candidates;
  }
  async close(): Promise<void> { this.closed = true; await this.runner.close(); }
}

backend-ts/src/wechat-setup-probe.ts.content:
/** 固定只读 CLI 适配；输出仅驻留内存，调试路径与摘要不进入业务结果。 */
import { spawn, type ChildProcess } from 'node:child_process';
import { WechatProbeUnavailable } from './wechat-setup.ts';

export class BoundedWechatCliRunner {
  private readonly options: { executable: string; environment?: NodeJS.ProcessEnv };
  private closed = false;
  private readonly active = new Map<ChildProcess, Promise<void>>();
  constructor(options: { executable: string; environment?: NodeJS.ProcessEnv }) { this.options = options; }
  async run(args: readonly string[], timeoutMs: number, signal?: AbortSignal): Promise<unknown> {
    if (this.closed || signal?.aborted) throw new WechatProbeUnavailable('wechat_tool_not_ready');
    if (!this.options.executable.trim()) throw new WechatProbeUnavailable('wechat_tool_unavailable');
    if (!Number.isFinite(timeoutMs) || timeoutMs < 1 || timeoutMs > 5000) throw new WechatProbeUnavailable('wechat_probe_failed');
    // 不允许通用执行器变为任意工具或写入入口。
    if (!['status','sessions'].includes(args[0]) || !args.includes('--strict-read-only')) throw new WechatProbeUnavailable('wechat_probe_failed');
    const child = spawn(this.options.executable, [...args], { env: this.options.environment, stdio: ['ignore','pipe','ignore'], shell: false });
    let done!: () => void;
    this.active.set(child, new Promise<void>(resolve => { done = resolve; }));
    try {
      return await new Promise<unknown>((resolve, reject) => {
        const chunks: Buffer[] = []; let bytes = 0; let failed = false;
        let unavailable = false;
        const abort = () => { failed = true; child.kill('SIGKILL'); };
        const timer = setTimeout(abort, timeoutMs);
        signal?.addEventListener('abort', abort, { once: true });
        if (signal?.aborted) abort();
        child.stdout!.on('data', (chunk: Buffer) => {
          bytes += chunk.length;
          if (bytes > 1024 * 1024) { failed = true; chunks.length = 0; child.kill('SIGKILL'); }
          else if (!failed) chunks.push(chunk);
        });
        child.on('error', (error: NodeJS.ErrnoException) => { failed = true; unavailable = error.code === 'ENOENT' || error.code === 'EACCES'; });
        child.once('close', code => {
          clearTimeout(timer);
          signal?.removeEventListener('abort', abort);
          if (failed || this.closed || code !== 0) { reject(new WechatProbeUnavailable(unavailable ? 'wechat_tool_unavailable' : 'wechat_tool_not_ready')); return; }
          try {
            const envelope = JSON.parse(Buffer.concat(chunks).toString('utf8'));
            if (!envelope || envelope.ok !== true || !envelope.data || typeof envelope.data !== 'object') throw new Error();
            resolve(envelope.data);
          } catch { reject(new WechatProbeUnavailable('wechat_probe_failed')); }
        });
      });
    } finally { this.active.delete(child); done(); }
  }
  async close(): Promise<void> {
    this.closed = true;
    const pending = [...this.active.values()];
    for (const child of this.active.keys()) child.kill('SIGKILL');
    await Promise.all(pending);
  }
}
export interface WechatCliRunner { run(args: readonly string[], timeoutMs: number, signal?: AbortSignal): Promise<unknown>; close(): Promise<void> }
export class WechatSetupProbe {
  private readonly runner: WechatCliRunner;
  constructor(options: { executable: string; environment?: NodeJS.ProcessEnv; runner?: WechatCliRunner }) {
    this.runner = options.runner ?? new BoundedWechatCliRunner(options);
  }
  async detect(signal?: AbortSignal): Promise<string> {
    const data = await this.runner.run(['status','--include-debug','--strict-read-only'], 5000, signal) as Record<string, any>;
    return parseConfiguredWechatAccount(data);
  }
  /** 仅在用户确认必要的列表访问同意后调用，列表及摘要立即丢弃。 */
  async confirm(account: string, signal?: AbortSignal): Promise<string> {
    if (await this.detect(signal) !== account) throw new WechatProbeUnavailable('wechat_account_changed');
    const data = await this.runner.run(['sessions','--type-filter','private','--limit','1','--strict-read-only'], 1000, signal) as Record<string, unknown>;
    if (!Array.isArray(data?.sessions)) throw new WechatProbeUnavailable('wechat_probe_failed');
    if (await this.detect(signal) !== account) throw new WechatProbeUnavailable('wechat_account_changed');
    return account;
  }
  close(): Promise<void> { return this.runner.close(); }
}

/** 只投影经只读与就绪证据核验的稳定账号。 */
export function parseConfiguredWechatAccount(data: unknown): string {
  const status = (data as { status?: Record<string, any> } | null)?.status;
  if (!status || status.account?.identity_configured !== true || status.account?.schema2_ready !== true || status.live_read_ok !== true || !['ready','degraded'].includes(status.readiness) || status.mode?.strict_read_only !== true) throw new WechatProbeUnavailable('wechat_tool_not_ready');
  const identity = status.account_debug?.wxid;
  if (typeof identity !== 'string' || !/^[A-Za-z0-9_.@-]{1,255}$/.test(identity)) throw new WechatProbeUnavailable('wechat_probe_failed');
  return identity;
}

backend-ts/src/wechat-setup.ts.content:
/** 账号连接业务；候选核验与数据库授权不依赖 DSH 会话或模型。 */
import { enrollHistorySnapshot, type HistorySession } from './wechat-history-enrollment.ts';
import { randomBytes, timingSafeEqual } from 'node:crypto';
import { HostStorageError, type HostStorage } from './host-storage.ts';

export class WechatSetupConflict extends HostStorageError {
  constructor() { super('wechat_identity_conflict'); }
}
export class WechatProbeUnavailable extends Error {
  readonly code: string;
  constructor(code = 'wechat_tool_not_ready') { super('微信读取工具尚不可用。'); this.code = code; }
}
export interface SetupGrant { mode: 'selected' | 'all_private'; historyAuthorized: boolean }
export interface WechatSetupStore {
  read(ownerId: string): Promise<string | null>;
  connect(ownerId: string, accountId: string, at: Date, grant: SetupGrant, assertCurrent?: () => void, historySessions?: readonly HistorySession[]): Promise<void>;
}
export interface SetupResult { state: string; account_id: string | null; candidate_token: string | null; failure_code: string | null }
const result = (state: string, account: string | null = null, token: string | null = null, failure: string | null = null): SetupResult =>
  ({ state, account_id: account, candidate_token: token, failure_code: failure });
export class WechatSetupService {
  private candidate: { account: string; token: string } | undefined;
  private tail: Promise<unknown> = Promise.resolve();
  private closed = false;
  private readonly options: { ownerId?: string; runtimeAccount?: string; store: WechatSetupStore;
    historySessions?: (account: string, signal?: AbortSignal) => Promise<readonly HistorySession[]>;
    probe: (signal?: AbortSignal) => Promise<string>; confirmProbe: (account: string, signal?: AbortSignal) => Promise<string>; clock?: () => Date; closeProbe?: () => Promise<void> };
  constructor(options: WechatSetupService['options']) { this.options = options; }
  private assertOpen(): void { if (this.closed) throw new HostStorageError('runtime_stopping'); }
  private async existing(): Promise<SetupResult | undefined> {
    if (!this.options.ownerId) return result('needs_owner');
    const account = await this.options.store.read(this.options.ownerId);
    if (!account) return undefined;
    if (this.options.runtimeAccount && this.options.runtimeAccount !== account) throw new WechatSetupConflict();
    return result(this.options.runtimeAccount === account ? 'connected' : 'restart_required', account);
  }
  private run(operation: (assertCurrent: () => void) => Promise<SetupResult>, externalAssert: () => void = () => {}): Promise<SetupResult> {
    const pending = this.tail.then(async () => {
      const assertCurrent = () => { this.assertOpen(); externalAssert(); };
      assertCurrent();
      try { const value = await operation(assertCurrent); assertCurrent(); return value; }
      catch (error) {
        if (error instanceof WechatSetupConflict) return result('conflict', null, null, 'wechat_identity_conflict');
        if (error instanceof WechatProbeUnavailable) {
          this.candidate = undefined;
          const code = ['wechat_tool_unavailable', 'wechat_tool_not_ready', 'wechat_account_changed'].includes(error.code) ? error.code : 'wechat_probe_failed';
          return result(code === 'wechat_account_changed' ? 'conflict' : code === 'wechat_tool_unavailable' ? 'tool_unavailable' : 'tool_not_ready', null, null, code);
        }
        throw error;
      }
    });
    this.tail = pending.catch(() => {});
    return pending;
  }
  status(assertCurrent?: () => void): Promise<SetupResult> { return this.run(async () => await this.existing() ?? result('needs_detection'), assertCurrent); }
  detect(assertCurrent?: () => void, signal?: AbortSignal): Promise<SetupResult> {
    return this.run(async current => {
      const existing = await this.existing(); if (existing) return existing;
      const account = await this.options.probe(signal); current();
      if (!/^[A-Za-z0-9_.@-]{1,255}$/.test(account)) throw new WechatProbeUnavailable('wechat_probe_failed');
      if (this.candidate?.account !== account) this.candidate = { account, token: randomBytes(32).toString('base64url') };
      return result('ready', account, this.candidate!.token);
    }, assertCurrent);
  }
  confirm(input: { candidate_token: string; mode?: 'selected' | 'all_private'; historyAuthorized?: boolean }, assertCurrent?: () => void, signal?: AbortSignal): Promise<SetupResult> {
    return this.run(async current => {
      const existing = await this.existing(); if (existing) return existing;
      if (input.mode !== undefined && !['selected','all_private'].includes(input.mode) || input.historyAuthorized !== undefined && typeof input.historyAuthorized !== 'boolean') throw new HostStorageError('setup_request_invalid');
      const token = typeof input.candidate_token === 'string' && input.candidate_token.length <= 128 ? Buffer.from(input.candidate_token) : Buffer.alloc(0);
      const expected = Buffer.from(this.candidate?.token ?? '');
      if (!this.candidate || token.length !== expected.length || !timingSafeEqual(token, expected)) return result('conflict', null, null, 'wechat_candidate_expired');
      const account = await this.options.probe(signal); current();
      if (account !== this.candidate.account) { this.candidate = undefined; return result('conflict', null, null, 'wechat_account_changed'); }
      if (await this.options.confirmProbe(account, signal) !== account) { this.candidate = undefined; return result('conflict', null, null, 'wechat_account_changed'); }
      current();
      let historySessions: readonly HistorySession[] | undefined;
      if (input.mode === 'all_private' && input.historyAuthorized) {
        if (!this.options.historySessions) throw new WechatProbeUnavailable();
        historySessions = await this.options.historySessions(account, signal); current();
        if (await this.options.probe(signal) !== account) { this.candidate = undefined; return result('conflict', null, null, 'wechat_account_changed'); }
        current();
      }
      await this.options.store.connect(this.options.ownerId!, account, this.options.clock?.() ?? new Date(), { mode: input.mode ?? 'selected', historyAuthorized: input.historyAuthorized ?? false }, current, historySessions);
      return result('restart_required', account);
    }, assertCurrent);
  }
  async close(): Promise<void> { this.closed = true; this.candidate = undefined; await this.options.closeProbe?.(); await this.tail; }
}

/** 沿用原表、UUID 与领域锁；领域错误在事务内转换，避免宿主抹去冲突类型。 */
export class PostgresWechatSetupStore implements WechatSetupStore {
  private readonly storage: Pick<HostStorage, 'businessTransaction'>;
  constructor(storage: Pick<HostStorage, 'businessTransaction'>) { this.storage = storage; }
  read(ownerId: string): Promise<string | null> {
    return this.storage.businessTransaction(async client => {
      const { rows } = await client.query("SELECT external_id,status FROM public.owner_channel_identity WHERE owner_id=$1 AND channel='wechat'", [ownerId]);
      if (!rows.length) return null;
      if (rows.length !== 1 || rows[0].status !== 'active') throw new WechatSetupConflict();
      return rows[0].external_id;
    });
  }
  connect(ownerId: string, accountId: string, at: Date, grant: SetupGrant, assertCurrent: () => void = () => {}, historySessions?: readonly HistorySession[]): Promise<void> {
    if (!/^[A-Za-z0-9_.@-]{1,255}$/.test(accountId) || !Number.isFinite(at.getTime()) || !['selected','all_private'].includes(grant.mode) || typeof grant.historyAuthorized !== 'boolean') throw new HostStorageError('setup_request_invalid');
    assertCurrent();
    return this.storage.businessTransaction(async client => {
      try {
        assertCurrent();
        await client.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [`owner:${ownerId}`]);
        await client.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [`wechat-setup-account:${accountId}`]);
        const { rows } = await client.query("SELECT owner_id,external_id,status FROM public.owner_channel_identity WHERE channel='wechat' AND (owner_id=$1 OR external_id=$2) FOR UPDATE", [ownerId, accountId]);
        if (rows.length) {
          if (rows.length === 1 && rows[0].owner_id === ownerId && rows[0].external_id === accountId && rows[0].status === 'active') return;
          throw new WechatSetupConflict();
        }
        await client.query("INSERT INTO public.owner_channel_identity(owner_id,channel,external_id,observed_name,verified_at) VALUES($1,'wechat',$2,$2,$3)", [ownerId, accountId, at]);
        await client.query("INSERT INTO public.wechat_sync_scope(owner_id,channel,account_scope,mode,granted_at) VALUES($1,'wechat',$2,$3,$4)", [ownerId, accountId, grant.mode, at]);
        if (grant.historyAuthorized && grant.mode === 'all_private') await client.query("INSERT INTO public.wechat_history_sync_authorization(owner_id,channel,account_scope,version,decision,decided_at) VALUES($1,'wechat',$2,1,'accepted',$3)", [ownerId, accountId, at]);
        await client.query('INSERT INTO public.front_sync_state(owner_id,enabled,enabled_at) VALUES($1,true,$2) ON CONFLICT(owner_id) DO UPDATE SET enabled=true,enabled_at=EXCLUDED.enabled_at,updated_at=now()', [ownerId, at]);
        if (grant.historyAuthorized && grant.mode === 'all_private') await enrollHistorySnapshot(client, ownerId, accountId, historySessions, at, assertCurrent);
        assertCurrent();
      } catch (error) {
        if (['23505','wechat_identity_conflict'].includes((error as {code?: string}).code ?? '')) throw new WechatSetupConflict();
        throw error;
      }
    });
  }
}

